import { util, runtime } from '@aws-appsync/utils';

const VP_TABLE = 'LMASA-AISTACK-4VKHCQQY3CJR-VirtualParticipant';

// Insertion sort via for...of only - the AppSync JS runtime doesn't support
// classic C-style for(;;) / while loops, or Array.prototype.sort with a
// comparator callback.
function insertSorted(sortedArr, item) {
  const result = [];
  let inserted = false;
  for (const existing of sortedArr) {
    if (!inserted) {
      const a = item.createdAt ? item.createdAt : '';
      const b = existing.createdAt ? existing.createdAt : '';
      if (a >= b) {
        result.push(item);
        inserted = true;
      }
    }
    result.push(existing);
  }
  if (!inserted) {
    result.push(item);
  }
  return result;
}

function mergeAndSort(owned, shared) {
  const combined = owned.concat(shared);
  const seen = {};
  let sorted = [];
  for (const item of combined) {
    if (item && item.id && !seen[item.id]) {
      seen[item.id] = true;
      sorted = insertSorted(sorted, item);
    }
  }
  return sorted;
}

// Fetches the full VP records for whatever ids VPGetSharedIds found, then
// merges them with the owned/scanned items from VPOwnerQueryOrAdminScan,
// dedupes, and sorts newest-first. Admins pass through unfiltered (matches
// today's behavior). If there's nothing shared, skips the BatchGetItem call
// entirely and returns the owned-only result right away.
export function request(ctx) {
  const owned = ctx.stash.primaryItems ? ctx.stash.primaryItems : [];

  if (ctx.stash.isAdmin) {
    return runtime.earlyReturn(owned);
  }

  const ids = ctx.stash.sharedVpIds ? ctx.stash.sharedVpIds : [];
  if (ids.length === 0) {
    return runtime.earlyReturn(mergeAndSort(owned, []));
  }

  const tables = {};
  tables[VP_TABLE] = {
    keys: ids.map((id) => util.dynamodb.toMapValues({ id })),
  };
  return { operation: 'BatchGetItem', tables };
}

export function response(ctx) {
  const owned = ctx.stash.primaryItems ? ctx.stash.primaryItems : [];
  const data = ctx.result.data ? ctx.result.data : {};
  const shared = data[VP_TABLE] ? data[VP_TABLE] : [];
  return mergeAndSort(owned, shared);
}
